export type EventHandler = (payload: any) => void;

export class EventBus {
  private listeners: Map<string, Set<EventHandler>> = new Map();

  on(eventName: string, handler: EventHandler): () => void {
    if (!this.listeners.has(eventName)) {
      this.listeners.set(eventName, new Set());
    }
    const set = this.listeners.get(eventName)!;
    set.add(handler);
    return () => {
      set.delete(handler);
    };
  }

  emit(eventName: string, payload: any): void {
    const set = this.listeners.get(eventName);
    if (!set) return;
    for (const handler of Array.from(set)) {
      try {
        handler(payload);
      } catch (err) {
        // Do not crash the bus if handlers throw
        // In a real system, we might log this
      }
    }
  }
}

import { randomUUID } from 'crypto';

export interface User {
  id: string;
  name: string;
  email: string;
}

export class UserService {
  private users: Map<string, User> = new Map();

  create(name: string, email: string): User {
    const id = randomUUID();
    const user: User = { id, name, email };
    this.users.set(id, user);
    return user;
  }

  list(): User[] {
    return Array.from(this.users.values());
  }

  get(id: string): User | undefined {
    return this.users.get(id);
  }

  update(id: string, updates: Partial<Omit<User, 'id'>>): User | undefined {
    const current = this.users.get(id);
    if (!current) return undefined;
    const updated: User = { ...current, ...updates };
    this.users.set(id, updated);
    return updated;
  }

  delete(id: string): boolean {
    return this.users.delete(id);
  }
}

import { randomUUID } from 'crypto';

export interface Project {
  id: string;
  name: string;
  description: string;
  members: string[]; // user IDs
}

export class ProjectService {
  private projects: Map<string, Project> = new Map();

  create(name: string, description: string): Project {
    const id = randomUUID();
    const project: Project = { id, name, description, members: [] };
    this.projects.set(id, project);
    return project;
  }

  list(): Project[] {
    return Array.from(this.projects.values());
  }

  get(id: string): Project | undefined {
    return this.projects.get(id);
  }

  update(id: string, updates: Partial<Omit<Project, 'id' | 'members'>>): Project | undefined {
    const current = this.projects.get(id);
    if (!current) return undefined;
    const updated: Project = { ...current, ...updates };
    this.projects.set(id, updated);
    return updated;
  }

  delete(id: string): boolean {
    return this.projects.delete(id);
  }

  addMember(projectId: string, userId: string): Project | undefined {
    const project = this.projects.get(projectId);
    if (!project) return undefined;
    if (!project.members.includes(userId)) {
      project.members.push(userId);
    }
    return project;
  }

  removeMember(projectId: string, userId: string): Project | undefined {
    const project = this.projects.get(projectId);
    if (!project) return undefined;
    project.members = project.members.filter((m) => m !== userId);
    return project;
  }
}

import { randomUUID } from 'crypto';
import { EventBus } from '../event-bus';

export type TaskStatus = 'todo' | 'in-progress' | 'done';

export interface Task {
  id: string;
  title: string;
  description: string;
  status: TaskStatus;
  assignee?: string; // user id
  projectId: string;
}

export class TaskService {
  private tasks: Map<string, Task> = new Map();

  constructor(private bus: EventBus) {}

  create(title: string, description: string, projectId: string, assignee?: string): Task {
    const id = randomUUID();
    const task: Task = {
      id,
      title,
      description,
      status: 'todo',
      assignee,
      projectId,
    };
    this.tasks.set(id, task);
    if (assignee) {
      this.bus.emit('task.assigned', { taskId: id, assignee });
    }
    this.bus.emit('task.created', { taskId: id, projectId });
    return task;
  }

  list(filter?: { projectId?: string }): Task[] {
    let list = Array.from(this.tasks.values());
    if (filter?.projectId) list = list.filter((t) => t.projectId === filter.projectId);
    return list;
  }

  get(id: string): Task | undefined {
    return this.tasks.get(id);
  }

  update(id: string, updates: Partial<Omit<Task, 'id' | 'status'>>): Task | undefined {
    const current = this.tasks.get(id);
    if (!current) return undefined;
    const prevAssignee = current.assignee;
    const updated: Task = { ...current, ...updates };
    this.tasks.set(id, updated);
    if (updates.assignee && updates.assignee !== prevAssignee) {
      this.bus.emit('task.assigned', { taskId: id, assignee: updates.assignee });
    }
    this.bus.emit('task.updated', { taskId: id });
    return updated;
  }

  delete(id: string): boolean {
    const existed = this.tasks.delete(id);
    if (existed) this.bus.emit('task.deleted', { taskId: id });
    return existed;
  }

  setStatus(id: string, nextStatus: TaskStatus): Task | undefined {
    const current = this.tasks.get(id);
    if (!current) return undefined;
    const allowed: Record<TaskStatus, TaskStatus[]> = {
      'todo': ['in-progress'],
      'in-progress': ['done'],
      'done': [],
    };
    if (!allowed[current.status].includes(nextStatus)) {
      throw new Error(`Invalid status transition from ${current.status} to ${nextStatus}`);
    }
    current.status = nextStatus;
    this.tasks.set(id, current);
    this.bus.emit('task.statusChanged', { taskId: id, status: nextStatus, assignee: current.assignee });
    return current;
  }

  assign(id: string, userId: string): Task | undefined {
    const current = this.tasks.get(id);
    if (!current) return undefined;
    current.assignee = userId;
    this.tasks.set(id, current);
    this.bus.emit('task.assigned', { taskId: id, assignee: userId });
    return current;
  }
}

import { randomUUID } from 'crypto';
import { EventBus } from '../event-bus';

export interface Comment {
  id: string;
  taskId: string;
  authorId: string;
  body: string;
  createdAt: number; // epoch ms
}

export class CommentService {
  private comments: Map<string, Comment> = new Map();

  constructor(private bus: EventBus) {}

  create(taskId: string, authorId: string, body: string): Comment {
    const id = randomUUID();
    const comment: Comment = { id, taskId, authorId, body, createdAt: Date.now() };
    this.comments.set(id, comment);
    this.bus.emit('comment.added', { commentId: id, taskId, authorId });
    return comment;
  }

  list(filter?: { taskId?: string }): Comment[] {
    let list = Array.from(this.comments.values());
    if (filter?.taskId) list = list.filter((c) => c.taskId === filter.taskId);
    return list.sort((a, b) => a.createdAt - b.createdAt);
  }

  get(id: string): Comment | undefined {
    return this.comments.get(id);
  }

  delete(id: string): boolean {
    const existed = this.comments.delete(id);
    if (existed) this.bus.emit('comment.deleted', { commentId: id });
    return existed;
  }
}

import { randomUUID } from 'crypto';
import { EventBus } from '../event-bus';

export interface Notification {
  id: string;
  userId: string;
  message: string;
  read: boolean;
  timestamp: number; // epoch ms
}

export class NotificationService {
  private notifications: Map<string, Notification> = new Map();

  constructor(private bus: EventBus) {
    // Subscriptions
    bus.on('task.assigned', ({ taskId, assignee }: { taskId: string; assignee: string }) => {
      this.create(assignee, `You have been assigned to task ${taskId}`);
    });
    bus.on('task.statusChanged', ({ taskId, assignee, status }: { taskId: string; assignee?: string; status: string }) => {
      if (assignee) this.create(assignee, `Task ${taskId} status changed to ${status}`);
    });
    bus.on('comment.added', ({ taskId, authorId }: { taskId: string; authorId: string }) => {
      // In a decoupled design, we don't know the assignee here. We rely on router to include such info in payload
      // But per spec, Comment Service publishes only comment.added with taskId and authorId. We'll notify author only if desired
      // Alternatively, we keep a lightweight subscription for task.assigned to map current assignees for notifications.
      // Simpler: rely on router to publish comment.added.enriched with assignee when it has that context.
    });
    // We'll also listen for enriched comment events to notify assignee
    bus.on('comment.added.enriched', ({ taskId, assignee, authorId }: { taskId: string; assignee?: string; authorId: string }) => {
      if (assignee) this.create(assignee, `New comment on your task ${taskId} by user ${authorId}`);
    });
  }

  private create(userId: string, message: string): Notification {
    const id = randomUUID();
    const notif: Notification = { id, userId, message, read: false, timestamp: Date.now() };
    this.notifications.set(id, notif);
    return notif;
  }

  list(filter?: { userId?: string }): Notification[] {
    let list = Array.from(this.notifications.values());
    if (filter?.userId) list = list.filter((n) => n.userId === filter.userId);
    return list.sort((a, b) => a.timestamp - b.timestamp);
  }

  get(id: string): Notification | undefined {
    return this.notifications.get(id);
  }

  markRead(id: string): Notification | undefined {
    const n = this.notifications.get(id);
    if (!n) return undefined;
    n.read = true;
    this.notifications.set(id, n);
    return n;
  }
}

import { IncomingMessage, ServerResponse } from 'http';
import { parse as parseUrl } from 'url';
import { EventBus } from './event-bus';
import { UserService } from './services/user-service';
import { ProjectService } from './services/project-service';
import { TaskService } from './services/task-service';
import { CommentService } from './services/comment-service';
import { NotificationService } from './services/notification-service';

export class ApiRouter {
  constructor(
    private bus: EventBus,
    private users: UserService,
    private projects: ProjectService,
    private tasks: TaskService,
    private comments: CommentService,
    private notifications: NotificationService,
  ) {}

  async handle(req: IncomingMessage, res: ServerResponse) {
    const url = parseUrl(req.url || '', true);
    const method = (req.method || 'GET').toUpperCase();
    const path = url.pathname || '/';

    const send = (code: number, body: any) => {
      const data = JSON.stringify(body);
      res.statusCode = code;
      res.setHeader('Content-Type', 'application/json');
      res.setHeader('Content-Length', Buffer.byteLength(data));
      res.end(data);
    };

    const notFound = () => send(404, { error: 'Not Found' });
    const badRequest = (msg: string) => send(400, { error: msg });

    const readBody = async () => {
      const chunks: any[] = [];
      for await (const chunk of req) chunks.push(chunk);
      const raw = Buffer.concat(chunks).toString('utf8');
      if (!raw) return {};
      try {
        return JSON.parse(raw);
      } catch (e) {
        return {};
      }
    };

    try {
      // Users
      if (path === '/users' && method === 'GET') {
        return send(200, this.users.list());
      }
      if (path === '/users' && method === 'POST') {
        const body = await readBody();
        if (!body.name || !body.email) return badRequest('name and email required');
        const user = this.users.create(body.name, body.email);
        return send(201, user);
      }
      if (path.startsWith('/users/') && ['GET', 'PUT', 'DELETE'].includes(method)) {
        const id = path.split('/')[2];
        if (method === 'GET') {
          const user = this.users.get(id);
          if (!user) return notFound();
          return send(200, user);
        }
        if (method === 'PUT') {
          const body = await readBody();
          const updated = this.users.update(id, { name: body.name, email: body.email });
          if (!updated) return notFound();
          return send(200, updated);
        }
        if (method === 'DELETE') {
          const ok = this.users.delete(id);
          if (!ok) return notFound();
          return send(204, {});
        }
      }

      // Projects
      if (path === '/projects' && method === 'GET') {
        return send(200, this.projects.list());
      }
      if (path === '/projects' && method === 'POST') {
        const body = await readBody();
        if (!body.name || !body.description) return badRequest('name and description required');
        const project = this.projects.create(body.name, body.description);
        return send(201, project);
      }
      if (path.startsWith('/projects/') && ['GET', 'PUT', 'DELETE'].includes(method)) {
        const id = path.split('/')[2];
        if (method === 'GET') {
          const project = this.projects.get(id);
          if (!project) return notFound();
          return send(200, project);
        }
        if (method === 'PUT') {
          const body = await readBody();
          const updated = this.projects.update(id, { name: body.name, description: body.description });
          if (!updated) return notFound();
          return send(200, updated);
        }
        if (method === 'DELETE') {
          const ok = this.projects.delete(id);
          if (!ok) return notFound();
          return send(204, {});
        }
      }

      if (path.startsWith('/projects/') && (method === 'POST' || method === 'DELETE') && path.endsWith('/members')) {
        const id = path.split('/')[2];
        const body = await readBody();
        if (!body.userId) return badRequest('userId required');
        const exists = this.users.get(body.userId);
        if (!exists) return badRequest('user does not exist');
        const project = method === 'POST' ? this.projects.addMember(id, body.userId) : this.projects.removeMember(id, body.userId);
        if (!project) return notFound();
        return send(200, project);
      }

      // Tasks
      if (path === '/tasks' && method === 'GET') {
        const projectId = (url.query.projectId as string) || undefined;
        return send(200, this.tasks.list({ projectId }));
      }
      if (path === '/tasks' && method === 'POST') {
        const body = await readBody();
        if (!body.title || !body.description || !body.projectId) return badRequest('title, description, projectId required');
        const project = this.projects.get(body.projectId);
        if (!project) return badRequest('project does not exist');
        const task = this.tasks.create(body.title, body.description, body.projectId, body.assignee);
        return send(201, task);
      }
      if (path.startsWith('/tasks/') && ['GET', 'PUT', 'DELETE'].includes(method)) {
        const id = path.split('/')[2];
        if (method === 'GET') {
          const task = this.tasks.get(id);
          if (!task) return notFound();
          return send(200, task);
        }
        if (method === 'PUT') {
          const body = await readBody();
          const updated = this.tasks.update(id, { title: body.title, description: body.description, assignee: body.assignee, projectId: body.projectId });
          if (!updated) return notFound();
          return send(200, updated);
        }
        if (method === 'DELETE') {
          const ok = this.tasks.delete(id);
          if (!ok) return notFound();
          return send(204, {});
        }
      }

      if (path.startsWith('/tasks/') && method === 'PUT' && path.endsWith('/status')) {
        const id = path.split('/')[2];
        const body = await readBody();
        try {
          const updated = this.tasks.setStatus(id, body.status);
          if (!updated) return notFound();
          return send(200, updated);
        } catch (e: any) {
          return badRequest(e.message || 'invalid status');
        }
      }
      if (path.startsWith('/tasks/') && method === 'PUT' && path.endsWith('/assign')) {
        const id = path.split('/')[2];
        const body = await readBody();
        const exists = this.users.get(body.userId);
        if (!exists) return badRequest('user does not exist');
        const updated = this.tasks.assign(id, body.userId);
        if (!updated) return notFound();
        return send(200, updated);
      }

      // Comments
      if (path === '/comments' && method === 'GET') {
        const taskId = (url.query.taskId as string) || undefined;
        return send(200, this.comments.list({ taskId }));
      }
      if (path === '/comments' && method === 'POST') {
        const body = await readBody();
        if (!body.taskId || !body.authorId || !body.body) return badRequest('taskId, authorId, body required');
        const task = this.tasks.get(body.taskId);
        if (!task) return badRequest('task does not exist');
        const author = this.users.get(body.authorId);
        if (!author) return badRequest('author does not exist');
        const comment = this.comments.create(body.taskId, body.authorId, body.body);
        // Enrich and notify assignee via enriched event
        this.bus.emit('comment.added.enriched', { taskId: body.taskId, assignee: task.assignee, authorId: body.authorId });
        return send(201, comment);
      }
      if (path.startsWith('/comments/') && ['GET', 'DELETE'].includes(method)) {
        const id = path.split('/')[2];
        if (method === 'GET') {
          const comment = this.comments.get(id);
          if (!comment) return notFound();
          return send(200, comment);
        }
        if (method === 'DELETE') {
          const ok = this.comments.delete(id);
          if (!ok) return notFound();
          return send(204, {});
        }
      }

      // Notifications
      if (path === '/notifications' && method === 'GET') {
        const userId = (url.query.userId as string) || undefined;
        return send(200, this.notifications.list({ userId }));
      }
      if (path.startsWith('/notifications/') && method === 'PUT' && path.endsWith('/read')) {
        const id = path.split('/')[2];
        const updated = this.notifications.markRead(id);
        if (!updated) return notFound();
        return send(200, updated);
      }

      return notFound();
    } catch (err: any) {
      res.statusCode = 500;
      res.setHeader('Content-Type', 'application/json');
      res.end(JSON.stringify({ error: 'Internal Server Error', detail: err?.message }));
    }
  }
}

import { createServer } from 'http';
import { EventBus } from './event-bus';
import { UserService } from './services/user-service';
import { ProjectService } from './services/project-service';
import { TaskService } from './services/task-service';
import { CommentService } from './services/comment-service';
import { NotificationService } from './services/notification-service';
import { ApiRouter } from './router';

const bus = new EventBus();

const userService = new UserService();
const projectService = new ProjectService();
const taskService = new TaskService(bus);
const commentService = new CommentService(bus);
const notificationService = new NotificationService(bus);

const router = new ApiRouter(bus, userService, projectService, taskService, commentService, notificationService);

const server = createServer((req, res) => router.handle(req, res));

const PORT = process.env.PORT ? parseInt(process.env.PORT, 10) : 3000;
server.listen(PORT, () => {
  console.log(`Task Management API running on http://localhost:${PORT}`);
});

import { spawn } from 'child_process';
import { request } from 'http';

function httpRequest(method: string, path: string, body?: any): Promise<any> {
  return new Promise((resolve, reject) => {
    const data = body ? JSON.stringify(body) : undefined;
    const req = request(
      {
        hostname: 'localhost',
        port: 3000,
        path,
        method,
        headers: {
          'Content-Type': 'application/json',
          'Content-Length': data ? Buffer.byteLength(data) : 0,
        },
      },
      (res) => {
        const chunks: any[] = [];
        res.on('data', (chunk) => chunks.push(chunk));
        res.on('end', () => {
          const raw = Buffer.concat(chunks).toString('utf8');
          try {
            resolve(raw ? JSON.parse(raw) : {});
          } catch (e) {
            resolve({});
          }
        });
      }
    );
    req.on('error', reject);
    if (data) req.write(data);
    req.end();
  });
}

